#include <stdio.h>
#include <stdint.h>

int main(void) {
    uint8_t a = 200;
    uint8_t b = 100;
    uint8_t c = a + b;
    printf("%d\n", c);
    return 0;
}

#include <stdio.h>

int main(void) {
    int arr[] = {10, 20, 30, 40};
    unsigned n = 4;
    for (unsigned i = n - 1; i >= 0; i--)
        printf("%d\n", arr[i]);
    return 0;
}

#include <stdio.h>
#include <stdint.h>

int main(void) {
    int8_t s = -3;
    int32_t w = s;
    unsigned char *p = (unsigned char *)&w;
    printf("%02X %02X\n", p[0], p[3]);
    return 0;
}
